public static void applySystemBarInsets(android.app.Activity activity) {
        if (activity == null || android.os.Build.VERSION.SDK_INT < 20) {
            return;
        }
        android.view.View content = activity.findViewById(android.R.id.content);
        if (content == null) {
            return;
        }
        int initialLeft = content.getPaddingLeft();
        int initialTop = content.getPaddingTop();
        int initialRight = content.getPaddingRight();
        int initialBottom = content.getPaddingBottom();
        content.setOnApplyWindowInsetsListener((view, insets) -> {
            view.setPadding(
                    initialLeft + insets.getSystemWindowInsetLeft(),
                    initialTop + insets.getSystemWindowInsetTop(),
                    initialRight + insets.getSystemWindowInsetRight(),
                    initialBottom + insets.getSystemWindowInsetBottom());
            return insets;
        });
        content.requestApplyInsets();
    }

public static String copyAssetToProject(
            Context context,
            String assetPath,
            String fileName) throws IOException {
        if (context == null || assetPath == null || assetPath.isEmpty()
                || fileName == null || fileName.isEmpty()) {
            throw new IOException("Missing bundled media input");
        }
        String safeName = fileName.replaceAll("[^A-Za-z0-9._-]", "_");
        if (safeName.isEmpty()) {
            throw new IOException("Bundled media name is invalid");
        }
        File directory = new File(context.getFilesDir(), "sample-media");
        if (!directory.exists() && !directory.mkdirs()) {
            throw new IOException("Cannot create sample media directory");
        }
        File output = new File(directory, safeName);
        if (output.isFile() && output.length() > 0) {
            return output.getAbsolutePath();
        }
        try (InputStream input = context.getAssets().open(assetPath);
             FileOutputStream stream = new FileOutputStream(output)) {
            byte[] buffer = new byte[16 * 1024];
            int count;
            while ((count = input.read(buffer)) != -1) {
                stream.write(buffer, 0, count);
            }
        } catch (IOException exception) {
            if (output.exists() && !output.delete()) {
                output.deleteOnExit();
            }
            throw exception;
        }
        if (!output.isFile() || output.length() == 0) {
            throw new IOException("Bundled media copy is empty");
        }
        return output.getAbsolutePath();
    }

public static String copyContentUriToCache(Context context, Uri uri) throws IOException {
        if (context == null || uri == null) {
            throw new IOException("Missing context or media URI");
        }
        String displayName = null;
        try (Cursor cursor = context.getContentResolver().query(
                uri,
                new String[]{OpenableColumns.DISPLAY_NAME},
                null,
                null,
                null)) {
            if (cursor != null && cursor.moveToFirst()) {
                int index = cursor.getColumnIndex(OpenableColumns.DISPLAY_NAME);
                if (index >= 0) {
                    displayName = cursor.getString(index);
                }
            }
        } catch (RuntimeException ignored) {
            // Fall back to a generated name when a provider exposes no metadata.
        }
        String safeName = (displayName == null ? "selected-media" : displayName)
                .replaceAll("[^A-Za-z0-9._-]", "_");
        if (safeName.isEmpty()) {
            safeName = "selected-media";
        }
        File directory = new File(
                new File(context.getCacheDir(), "selected-media"),
                String.valueOf(System.currentTimeMillis()));
        if (!directory.exists() && !directory.mkdirs()) {
            throw new IOException("Cannot create media cache directory");
        }
        // SDK asset-package parsers can require the original UUID-based file name.
        File output = new File(directory, safeName);
        try (InputStream input = context.getContentResolver().openInputStream(uri);
             FileOutputStream stream = new FileOutputStream(output)) {
            if (input == null) {
                throw new IOException("Cannot open selected media");
            }
            byte[] buffer = new byte[16 * 1024];
            int count;
            while ((count = input.read(buffer)) != -1) {
                stream.write(buffer, 0, count);
            }
        }
        return output.getAbsolutePath();
    }

public static File copyToProjectFile(Context context, Uri uri) throws IOException {
        if (context == null || uri == null) {
            throw new IllegalArgumentException("context and uri are required");
        }
        String displayName = "";
        try (Cursor cursor = context.getContentResolver().query(
                uri,
                new String[]{OpenableColumns.DISPLAY_NAME},
                null,
                null,
                null)) {
            if (cursor != null && cursor.moveToFirst()) {
                int column = cursor.getColumnIndex(OpenableColumns.DISPLAY_NAME);
                if (column >= 0) {
                    String value = cursor.getString(column);
                    displayName = value == null ? "" : value;
                }
            }
        }
        if (displayName.isEmpty()) {
            String mimeType = context.getContentResolver().getType(uri);
            String extension = "bin";
            if ("video/mp4".equals(mimeType)) {
                extension = "mp4";
            } else if ("image/jpeg".equals(mimeType)) {
                extension = "jpg";
            } else if ("image/png".equals(mimeType)) {
                extension = "png";
            }
            displayName = "media." + extension;
        }
        String safeName = displayName.replaceAll("[^a-zA-Z0-9._-]", "_");
        if (safeName.isEmpty()) {
            safeName = "media.bin";
        }
        File projectDir = new File(context.getFilesDir(), "project-media");
        if (!projectDir.exists() && !projectDir.mkdirs()) {
            throw new IOException("Cannot create project media directory: " + projectDir);
        }
        File outputFile = new File(projectDir, UUID.randomUUID() + "_" + safeName);
        try {
            try (InputStream input = context.getContentResolver().openInputStream(uri);
                 FileOutputStream output = new FileOutputStream(outputFile)) {
                if (input == null) {
                    throw new IOException("Cannot open selected media: " + uri);
                }
                byte[] buffer = new byte[64 * 1024];
                int read;
                while ((read = input.read(buffer)) != -1) {
                    output.write(buffer, 0, read);
                }
            }
        } catch (IOException exception) {
            if (outputFile.isFile()) {
                outputFile.delete();
            }
            throw exception;
        }
        return outputFile;
    }

