        try {
            android.content.SharedPreferences preferences = context.getSharedPreferences(
                    "meishe_projects",
                    Context.MODE_PRIVATE);
            String current = preferences.getString(projectId, "");
            JSONObject project = current == null || current.isEmpty()
                    ? new JSONObject()
