        if (outputHeight != null && outputHeight > 0) {
            configurations = new Hashtable<>();
            configurations.put(NvsMediaFileConvertor.CONVERTOR_CUSTOM_VIDEO_HEIGHT, outputHeight);
        }
        return convertor.convertMeidaFile(
                sourcePath,
                outputPath,
                true,
                trimInUs,
                trimOutUs,
